import { useState } from "react";
import { Link } from "react-router-dom";

function Home() {
  const [openMenu, setOpenMenu] = useState(null);

  const dashboardItems = [
    { title: "Add Student", desc: "Add new students", path: "/add" },
    { title: "Attendance", desc: "Mark attendance", path: "/attendance" },
    { title: "Marks Entry", desc: "Add marks", path: "/marks" },
    { title: "Report Card", desc: "View report cards", path: "/marks-report" },
    { title: "Student Profiles", desc: "View/Edit profiles", path: "/profile" },
  ];

  return (
    <div className="container">
      <h2>Dashboard</h2>
      <div className="dashboard-grid">
        {dashboardItems.map((item, index) => (
          <div key={index} className="dashboard-card">
            <Link to={item.path} className="card-link">
              <h3>{item.title}</h3>
              <p>{item.desc}</p>
            </Link>

            {/* 3-dot menu */}
            <div className="dot-menu-wrapper">
              <span
                className="dot-menu"
                onClick={() =>
                  setOpenMenu(openMenu === index ? null : index)
                }
              >
                ⋮
              </span>
              {openMenu === index && (
                <div className="dot-menu-content">
                  <button>View</button>
                  <button>Edit</button>
                  <button>Delete</button>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Home;
